// ========================================
// Set Follow-up After Bot Sends Quote
// بعد ما البوت يرسل السعر للعميل
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const DELAYS = {
  quoted:       30,
  interested:   120,
  followup:     1440,
  // manual_quote / closed / lost / handoff → no follow-up
};

const ctx         = $input.first().json;
const phone       = ctx.phone;
const newStage    = ctx.newStage || 'quoted';
const destination = ctx.destination || null;
const name        = ctx.name || null;

if (!phone || !DELAYS[newStage]) {
  return $input.all(); // محظور → skip
}

const nextFollowup = new Date(Date.now() + DELAYS[newStage] * 60 * 1000).toISOString();

// Upsert بدون conflict على phone
await fetch(`${SUPABASE_URL}/rest/v1/leads`, {
  method: 'POST',
  headers: {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'resolution=merge-duplicates,return=representation',
  },
  body: JSON.stringify({
    phone,
    name,
    destination,
    stage: newStage,
    follow_up_count: 0,
    next_followup:   nextFollowup,
    paused: false,
  }),
});

return $input.all();
